 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    # Full, non-background lines are the dividers between equal-sized panels.
    divider_rows = [r for r, row in enumerate(grid)
                    if len(set(row)) == 1 and row[0] != background]
    divider_cols = [c for c in range(w)
                    if len({grid[r][c] for r in range(h)}) == 1
                    and grid[0][c] != background]
    rb = [-1] + divider_rows + [h]
    cb = [-1] + divider_cols + [w]
    rparts = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cparts = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]

    # The panel containing the most non-background cells holds the motif.
    source = None
    best = -1
    for ri, (r0, r1) in enumerate(rparts):
        for ci, (c0, c1) in enumerate(cparts):
            score = sum(grid[r][c] != background
                        for r in range(r0, r1) for c in range(c0, c1))
            if score > best:
                best, source = score, (ri, ci)
    sri, sci = source
    sr0, sr1 = rparts[sri]
    sc0, sc1 = cparts[sci]
    motif = [row[sc0:sc1] for row in grid[sr0:sr1]]

    out = [row[:] for row in grid]
    for r0, r1 in rparts:
        for c0, c1 in cparts:
            if r1 - r0 == len(motif) and c1 - c0 == len(motif[0]):
                for i, row in enumerate(motif):
                    out[r0 + i][c0:c1] = row[:]
    return out
